/-- The connectivity relation, aka ξ in Oxley's book -/
def Matroid.ConnectivityRelation (M : Matroid α) (e f : α) : Prop :=
  e = f ∨ ∃ C : Set α, C ⊆ M.E ∧ M.Circuit C ∧ e ∈ C ∧ f ∈ C

